-- Setup CS (Cyber Security) Exam System
-- Table 1: Student Verification Table (3rd Year CSE)
-- Table 2: Results Table

-- Drop existing tables if they exist
DROP TABLE IF EXISTS "3rdcsecsresults" CASCADE;
DROP TABLE IF EXISTS "3rdcsecs" CASCADE;

-- Create Student Verification Table
CREATE TABLE "3rdcsecs" (
    id SERIAL PRIMARY KEY,
    roll_number VARCHAR(20) UNIQUE NOT NULL,
    unique_code VARCHAR(20) NOT NULL DEFAULT 'cs771',
    is_active BOOLEAN DEFAULT TRUE,
    verified_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create Results Table
CREATE TABLE "3rdcsecsresults" (
    id SERIAL PRIMARY KEY,
    roll_number VARCHAR(20) NOT NULL,
    correct_answers INTEGER NOT NULL,
    wrong_answers INTEGER NOT NULL,
    total_questions INTEGER NOT NULL DEFAULT 10,
    marks DECIMAL(5,2) NOT NULL,
    percentage DECIMAL(5,2) NOT NULL,
    user_answers JSONB,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (roll_number) REFERENCES "3rdcsecs"(roll_number) ON DELETE CASCADE
);

-- Insert all 246 roll numbers with unique code 'cs771' (same students as ALC)

-- Create indexes for better performance
CREATE INDEX idx_cs_roll_number ON "3rdcsecs"(roll_number);
CREATE INDEX idx_cs_results_roll_number ON "3rdcsecsresults"(roll_number);
CREATE INDEX idx_cs_created_at ON "3rdcsecsresults"(created_at);

-- Verify data
SELECT COUNT(*) as total_students FROM "3rdcsecs";
